// tempest.selftest.mjs — invariants for /tempest/. `preflight` runs this.
//
//   node games/tempest/test/tempest.selftest.mjs
//
// What it is for: this surface ships a *compiled* artefact. `tempest.wasm` is
// built from `core/` in a sandbox and committed, because the games surface has
// no build step on its deploy path and should not grow one. That buys a fast,
// dependency-free deploy and costs one risk — the wasm and the Rust it came
// from can drift apart silently.
//
// `test/golden.json` closes that. It is generated by `tempest golden` from the
// Rust, and BOTH sides check it:
//
//   * `cargo test` asserts the Rust still reproduces the file.
//   * this file asserts the committed wasm still reproduces the file.
//
// So editing the Rust without rebuilding the wasm fails here; rebuilding
// without regenerating the goldens fails there. There is no quiet way to be
// out of step.
//
// It also drives the real `js/engine.js`, not a copy of it, so the wire format
// is under test end to end.

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, '..');

let checks = 0;
let failures = 0;

function ok(cond, what) {
  checks++;
  if (!cond) {
    failures++;
    console.error(`  ✗ ${what}`);
  }
}

function eq(got, want, what) {
  const a = JSON.stringify(got);
  const b = JSON.stringify(want);
  checks++;
  if (a !== b) {
    failures++;
    console.error(`  ✗ ${what}\n      got  ${a}\n      want ${b}`);
  }
}

function section(name) {
  console.log(`\n${name}`);
}

// --- load the shipped engine.js exactly as the page does -------------------
// It is an IIFE that attaches to globalThis, so running it is enough — the
// same trick the rest of the /pressure/ family's selftests use.
for (const f of ['js/engine.js', 'js/render.js']) {
  const src = readFileSync(join(ROOT, f), 'utf8');
  try {
    new Function(src)();
  } catch (e) {
    console.error(`FATAL: ${f} did not evaluate: ${e.message}`);
    process.exit(1);
  }
}
// game.js touches the DOM on load, so it is only syntax-checked here.
try {
  new Function(readFileSync(join(ROOT, 'js/game.js'), 'utf8'));
} catch (e) {
  console.error(`FATAL: js/game.js does not parse: ${e.message}`);
  process.exit(1);
}

const golden = JSON.parse(readFileSync(join(ROOT, 'test/golden.json'), 'utf8'));
const pack = JSON.parse(readFileSync(join(ROOT, 'levels.json'), 'utf8'));
const wasmBytes = readFileSync(join(ROOT, 'tempest.wasm'));
const { epoch } = await Tempest.loadBytes(
  wasmBytes.buffer.slice(wasmBytes.byteOffset, wasmBytes.byteOffset + wasmBytes.byteLength)
);

section('epochs agree');
eq(epoch, golden.epoch, 'tempest.wasm epoch matches golden.json');
eq(pack.epoch, golden.epoch, 'levels.json epoch matches golden.json');

// --- the drift gate --------------------------------------------------------

const ACTION_BY_NAME = {
  hold: Tempest.ACTION.hold,
  fire: Tempest.ACTION.fire,
  cw: Tempest.ACTION.cw,
  ccw: Tempest.ACTION.ccw,
};
const pattern = golden.script.split(',').map((n) => {
  const a = ACTION_BY_NAME[n];
  if (a === undefined) throw new Error(`golden.json names an unknown action: ${n}`);
  return a;
});

// The module instance is private to engine.js, so re-instantiate one here for
// the raw-wire path. Same bytes, so same behaviour.
const { instance } = await WebAssembly.instantiate(
  wasmBytes.buffer.slice(wasmBytes.byteOffset, wasmBytes.byteOffset + wasmBytes.byteLength),
  {}
);
const wasmExports = instance.exports;

const OUTCOME = ['running', 'cleared', 'breached', 'stalled'];

section(`golden vectors (${golden.cases.length} boards)`);
for (const c of golden.cases) {
  const label = c.name.slice(0, 46);
  const bytes = c.wire.length * 4;
  const ptr = wasmExports.tp_alloc(bytes);
  ok(ptr !== 0, `${label}: allocation`);
  new Int32Array(wasmExports.memory.buffer).set(Int32Array.from(c.wire), ptr >> 2);
  const h = wasmExports.tp_new(ptr, c.wire.length, c.startLane);
  wasmExports.tp_free(ptr, bytes);
  ok(h >= 0, `${label}: wasm accepted the wire`);
  if (h < 0) continue;

  // Slack under each opening, read before a single tick is played.
  eq(
    [0, 1, 2].map((o) => wasmExports.tp_slack(h, o)),
    c.openSlack,
    `${label}: slack per opening`
  );
  const best = Math.max(...c.openSlack);
  eq(best, c.slack, `${label}: the best opening is the unconstrained slack`);
  eq(
    Math.max(c.openSlack[0], c.openSlack[1]) - Math.min(c.openSlack[0], c.openSlack[1]),
    c.wrongWayCost,
    `${label}: wrong-way cost is the gap between the directions`
  );

  // Replay the fixed script and compare the outcome tick for tick.
  let outcome = 'running';
  for (let i = 0; i < golden.ticks; i++) {
    const code = wasmExports.tp_step(h, pattern[i % pattern.length]);
    outcome = OUTCOME[code] || 'running';
    if (outcome !== 'running') break;
  }
  const killPtr = wasmExports.tp_kills(h);
  const killLen = wasmExports.tp_kills_len(h);
  const kills = Array.from(
    new Int32Array(wasmExports.memory.buffer, killPtr, killLen)
  );
  eq(kills, c.kills, `${label}: kill log`);

  // The outcome string carries the tick, so this compares the timing too.
  const tickNow = new Int32Array(
    wasmExports.memory.buffer,
    wasmExports.tp_state(h),
    1
  )[0];
  const rendered =
    outcome === 'running'
      ? 'running'
      : outcome === 'cleared'
        ? `cleared@${tickNow}`
        : outcome === 'breached'
          ? `breached@${tickNow}:${c.replay.split(':')[1] ?? ''}`
          : `stalled@${tickNow}`;
  ok(
    rendered.split(':')[0] === c.replay.split(':')[0],
    `${label}: replay outcome — got ${rendered}, want ${c.replay}`
  );

  eq(wasmExports.tp_lost_at(h), c.lostAt, `${label}: the tick the run was lost`);
  eq(wasmExports.tp_doomed_for(h), c.doomedFor, `${label}: ticks played after losing`);
  const verdictLen = wasmExports.tp_autopsy_len(h);
  ok(verdictLen > 10, `${label}: the autopsy says something`);
  wasmExports.tp_drop(h);
}

// --- the shipped pack ------------------------------------------------------

section(`the level pack (${pack.levels.length} levels)`);
let waves = 0;
let committing = 0;
let minSlack = Infinity;
for (const lvl of pack.levels) {
  const w = lvl.web;
  const label = `level ${lvl.index}`;
  ok(w.lanes >= 8 && w.lanes <= 16, `${label}: lane count in range`);
  eq(w.verts.length, w.closed ? w.lanes : w.lanes + 1, `${label}: vertex count`);
  eq(w.seats.length, w.lanes, `${label}: one seat per lane`);
  eq(w.step.length, w.closed ? w.lanes : w.lanes - 1, `${label}: one cost per travelled lane`);
  ok(
    w.step.every((s) => s >= 2 && s <= 22),
    `${label}: every lane cost is in range`
  );
  ok(lvl.waves.length >= 3, `${label}: has waves`);
  for (let i = 0; i < lvl.waves.length; i++) {
    const wave = lvl.waves[i];
    const cert = wave.cert;
    waves++;
    if (cert.commits) committing++;
    minSlack = Math.min(minSlack, cert.slack);
    ok(cert.holdable, `${label} wave ${i}: certified holdable`);
    ok(cert.slack >= 0, `${label} wave ${i}: slack is a real number`);
    ok(
      wave.worstLane >= 0 && wave.worstLane < w.lanes,
      `${label} wave ${i}: worst lane is a lane`
    );
    eq(
      cert.tour.length,
      wave.threats.length,
      `${label} wave ${i}: the certified play kills everything exactly once`
    );
    ok(
      cert.tour.every((s) => s.margin >= 0 && s.lane >= 0 && s.lane < w.lanes),
      `${label} wave ${i}: every shot in the tour is legal`
    );
    ok(
      Math.max(cert.openSlack.cw, cert.openSlack.ccw, cert.openSlack.stand) === cert.slack,
      `${label} wave ${i}: the best opening equals the slack`
    );
    for (let t = 0; t < wave.threats.length; t++) {
      const th = wave.threats[t];
      if (th.parent >= 0) {
        ok(th.parent < t, `${label} wave ${i}: child ${t} follows its parent`);
        ok(th.entry === null, `${label} wave ${i}: child ${t} has no entry of its own`);
        eq(
          wave.threats[th.parent].kind,
          'tanker',
          `${label} wave ${i}: child ${t} hangs off a tanker`
        );
      } else {
        ok(th.entry !== null, `${label} wave ${i}: root ${t} enters somewhere`);
        ok(
          th.entry.lane >= 0 && th.entry.lane < w.lanes,
          `${label} wave ${i}: root ${t} enters a real lane`
        );
      }
    }
  }
}

// --- the encoder the browser actually uses ---------------------------------

section('the browser path');
{
  const lvl = pack.levels[pack.levels.length - 1];
  const wave = lvl.waves[0];
  // Start where the certificate was taken. The pack certifies each wave from
  // the *worst* lane it could be entered in, not from lane 0, so comparing
  // against a run started anywhere else compares two different questions.
  const run = new Tempest.Run(lvl.web, wave, wave.worstLane);
  const st = run.state();
  eq(st.threats.length, wave.threats.length, 'engine.js encodes every threat');
  eq(st.tick, 0, 'a fresh run starts at tick 0');
  eq(st.lane, wave.worstLane, 'and in the lane it was given');
  ok(st.outcome === 'running', 'and it is running');
  const openings = run.openings();
  ok(openings !== null, 'openings are readable through engine.js');
  eq(
    [openings.cw, openings.ccw, openings.stand],
    [
      wave.cert.openSlack.cw >= 0,
      wave.cert.openSlack.ccw >= 0,
      wave.cert.openSlack.stand >= 0,
    ],
    'openings agree with the certificate the pack shipped'
  );
  eq(
    [run.slack(0), run.slack(1), run.slack(2)],
    [wave.cert.openSlack.cw, wave.cert.openSlack.ccw, wave.cert.openSlack.stand],
    'and so does the slack, tick for tick — the wasm re-derives the pack'
  );
  // Doing nothing must lose: if a wave clears itself, it is not a wave.
  for (let i = 0; i < 900; i++) {
    if (run.step(Tempest.ACTION.hold) !== 'running') break;
  }
  eq(run.state().outcome, 'breached', 'standing still loses');
  const a = run.autopsy();
  ok(a.verdict.length > 10, 'and the autopsy explains it');
  ok(a.lostAt >= 0, 'and names the tick it became unwinnable');
  run.dispose();
}

section('the pack as a whole');
ok(waves >= 40, `enough content: ${waves} certified waves`);
ok(minSlack >= 0, `tightest wave in the pack has ${minSlack} ticks of slack`);
ok(
  committing * 2 >= waves,
  `the web decides at least half the waves (${committing}/${waves})`
);
ok(Tempest.View !== undefined, 'render.js defines a View');

console.log(
  `\n${failures === 0 ? 'ok' : 'FAILED'} — ${checks - failures}/${checks} checks passed`
);
if (failures) process.exit(1);
